import React, { useCallback, useEffect, useMemo, useState } from "react";

import {
  Button,
  Card,
  Col,
  Container,
  FloatingLabel,
  Form,
  Row,
} from "react-bootstrap";

import { DatePicker, Empty, Statistic, Table, Tag, notification } from "antd";

import GetApiCall from "../../helpers/GetApi.js";

import dayjs from "dayjs";
import utc from "dayjs/plugin/utc";
import timezone from "dayjs/plugin/timezone";

dayjs.extend(utc);
dayjs.extend(timezone);
const { RangePicker } = DatePicker;

const IST_TIMEZONE = "UTC";

function Attendence() {
  const pageSize = 15;
  const formatIST = (value, format = "DD MMM YYYY, hh:mm A") => {
    if (!value) return "-";

    const date = dayjs.utc(value);

    if (!date.isValid()) return "-";

    return date.tz(IST_TIMEZONE).format(format);
  };

  const [attendanceData, setAttendanceData] = useState([]);
  const [loading, setLoading] = useState(false);

  const [dates, setDates] = useState(null);
  const [appliedDates, setAppliedDates] = useState(null);

  const [searchText, setSearchText] = useState("");
  const [appliedSearch, setAppliedSearch] = useState("");

  const [punchType, setPunchType] = useState("");
  const [appliedPunchType, setAppliedPunchType] = useState("");

  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);

  const [summary, setSummary] = useState({
    totalPunches: 0,
    totalIN: 0,
    totalOUT: 0,
    totalDevices: 0,
    totalMembers: 0,
  });
  const userData =
    localStorage.getItem("user") && JSON.parse(localStorage.getItem("user"));

  const userRole = String(userData?.role || "").toUpperCase();

  const userBranchId = userData?.branch_id || userData?.fld_branch_id || "";

  const canViewAllBranches = userRole === "SUPER ADMIN";

  const [branches, setBranches] = useState([]);
  const [branchFilter, setBranchFilter] = useState(
    canViewAllBranches ? "" : userBranchId,
  );
  const [appliedBranch, setAppliedBranch] = useState(
    canViewAllBranches ? "" : userBranchId,
  );
  const fetchData = useCallback(
    async (requestedPage = page) => {
      setLoading(true);

      try {
        const queryParams = new URLSearchParams({
          page: String(requestedPage),
          limit: String(pageSize),
        });

        // Date filter
        if (Array.isArray(appliedDates) && appliedDates[0] && appliedDates[1]) {
          queryParams.set("fromDate", appliedDates[0].format("YYYY-MM-DD"));

          queryParams.set("toDate", appliedDates[1].format("YYYY-MM-DD"));
        }

        // Search filter
        if (appliedSearch?.trim()) {
          queryParams.set("search", appliedSearch.trim());
        }

        // Punch type filter
        if (appliedPunchType) {
          queryParams.set("punchType", appliedPunchType);
        }

        // Branch filter
        if (appliedBranch) {
          queryParams.set("branchId", String(appliedBranch));
        }

        const url = `attendance/history?${queryParams.toString()}`;

        console.log("Attendance API URL:", url);

        const response = await GetApiCall.getRequest(url);

        const json = await response.json();

        if (!response.ok || json.success === false) {
          throw new Error(
            json.message || json.error || "Unable to fetch attendance history",
          );
        }

        console.log("Attendance API response:", json);

        setAttendanceData(Array.isArray(json.data) ? json.data : []);

        setTotal(Number(json.total || 0));

        setPage(Number(json.page || requestedPage));

        setSummary({
          totalPunches: Number(json.summary?.totalPunches || 0),
          totalIN: Number(json.summary?.totalIN || 0),
          totalOUT: Number(json.summary?.totalOUT || 0),
          totalDevices: Number(json.summary?.totalDevices || 0),
          totalMembers: Number(json.summary?.totalMembers || 0),
        });
      } catch (error) {
        console.error("Attendance history fetch error:", error);

        setAttendanceData([]);
        setTotal(0);

        setSummary({
          totalPunches: 0,
          totalIN: 0,
          totalOUT: 0,
          totalDevices: 0,
          totalMembers: 0,
        });

        notification.error({
          message: "Attendance Error",
          description: error.message || "Unable to fetch attendance history",
        });
      } finally {
        setLoading(false);
      }
    },
    [page, appliedDates, appliedSearch, appliedPunchType, appliedBranch],
  );

  useEffect(() => {
    fetchData(page);
  }, [page, fetchData]);

  const applyFilters = () => {
    setPage(1);
    setAppliedDates(dates);
    setAppliedSearch(searchText);
    setAppliedPunchType(punchType);
    setAppliedBranch(canViewAllBranches ? branchFilter : userBranchId);
  };

  const clearFilters = () => {
    setDates(null);
    setAppliedDates(null);

    setSearchText("");
    setAppliedSearch("");

    setPunchType("");
    setAppliedPunchType("");

    const defaultBranch = canViewAllBranches ? "" : userBranchId;

    setBranchFilter(defaultBranch);
    setAppliedBranch(defaultBranch);

    setPage(1);
  };
  // const loadBranches = useCallback(async () => {
  //   try {
  //     const response = await GetApiCall.getRequest("GetBranches");
  //     const json = await response.json();

  //     if (!response.ok) {
  //       throw new Error(json.message || "Unable to fetch branches");
  //     }

  //     const list = Array.isArray(json)
  //       ? json
  //       : Array.isArray(json.data)
  //         ? json.data
  //         : Array.isArray(json.branches)
  //           ? json.branches
  //           : [];

  //     setBranches(list);
  //   } catch (error) {
  //     console.error("Branch fetch error:", error);

  //     setBranches([]);

  //     notification.error({
  //       message: "Branch Error",
  //       description: error.message || "Unable to fetch branches",
  //     });
  //   }
  // }, []);
  const loadBranches = useCallback(async () => {
    try {
      const response = await GetApiCall.getRequest("GetBranches");
      const json = await response.json();

      if (!response.ok) {
        throw new Error(json.message || "Unable to fetch branches");
      }

      const list = Array.isArray(json)
        ? json
        : Array.isArray(json.data)
          ? json.data
          : Array.isArray(json.branches)
            ? json.branches
            : [];

      setBranches(list);
    } catch (error) {
      console.error("Branch fetch error:", error);

      setBranches([]);

      notification.error({
        message: "Branch Error",
        description: error.message || "Unable to fetch branches",
      });
    }
  }, []);
  const getPunchTypeTag = (value) => {
    const normalizedValue = String(value || "")
      .trim()
      .toUpperCase();

    if (normalizedValue === "IN") {
      return <Tag color="green">IN</Tag>;
    }

    if (normalizedValue === "OUT") {
      return <Tag color="red">OUT</Tag>;
    }

    return <Tag>{value || "Unknown"}</Tag>;
  };

  const columns = [
    {
      title: "#",
      key: "serialNumber",
      width: 65,
      fixed: "left",
      render: (_, __, index) => (page - 1) * pageSize + index + 1,
    },
    {
      title: "Member",
      key: "member",
      width: 210,
      fixed: "left",
      render: (_, record) => (
        <div>
          <div className="fw-semibold">
            {record.member_name || "Unknown Member"}
          </div>

          <small className="text-muted">
            {record.membership_number || `PIN: ${record.user_sn || "-"}`}
          </small>
        </div>
      ),
    },
    {
      title: "Mobile Number",
      dataIndex: "member_mobile",
      key: "memberMobile",
      width: 140,
      render: (value, record) => value || record.user_sn || "-",
    },
    {
      title: "Punch Date",
      dataIndex: "punch_time",
      key: "punchDate",
      width: 135,
      sorter: (a, b) =>
        dayjs(a.punch_time).valueOf() - dayjs(b.punch_time).valueOf(),
      render: (value) => formatIST(value, "DD MMM YYYY"),
    },
    {
      title: "Punch Time",
      dataIndex: "punch_time",
      key: "punchTime",
      width: 120,
      render: (value) => formatIST(value, "hh:mm:ss A"),
    },
    {
      title: "Type",
      dataIndex: "punch_type",
      key: "punchType",
      width: 90,
      render: getPunchTypeTag,
    },
    {
      title: "Machine",
      key: "machine",
      width: 250,
      render: (_, record) => (
        <div>
          <div className="fw-semibold">
            {record.machine_name || "Unknown Machine"}
          </div>

          <small className="text-muted">{record.device_sn || "-"}</small>
        </div>
      ),
    },
    {
      title: "Branch",
      dataIndex: "branch_name",
      key: "branchName",
      width: 160,
      render: (value) => value || "-",
    },
    {
      title: "Source",
      dataIndex: "source",
      key: "source",
      width: 120,
      render: (value) =>
        value ? <Tag color="blue">{value}</Tag> : <Tag>Unknown</Tag>,
    },
    {
      title: "Received At",
      dataIndex: "created_at",
      key: "createdAt",
      width: 190,
      render: (value) => formatIST(value),
    },
  ];
  useEffect(() => {
    loadBranches();
  }, [loadBranches]);
  return (
    <section className="inner-section">
      <Container>
        <Row className="mb-4">
          <Col lg={12}>
            <h2 className="section-title mb-2">Attendance History</h2>

            <p className="text-muted text-center">
              A complete overview of your attendance activity.
            </p>
          </Col>
        </Row>

        {/* <Row className="g-3 mb-4">
          <Col xl={3} md={6}>
            <Card className="h-100 border-0 shadow-sm">
              <Card.Body>
                <Statistic title="Total Punches" value={summary.totalPunches} />
              </Card.Body>
            </Card>
          </Col>

          <Col xl={3} md={6}>
            <Card className="h-100 border-0 shadow-sm">
              <Card.Body>
                <Statistic title="Total Entires" value={summary.totalIN} />
              </Card.Body>
            </Card>
          </Col>

          <Col xl={2} md={6}>
            <Card className="h-100 border-0 shadow-sm">
              <Card.Body>
                <Statistic title="Total Exits" value={summary.totalOUT} />
              </Card.Body>
            </Card>
          </Col>

          <Col xl={3} md={6}>
            <Card className="h-100 border-0 shadow-sm">
              <Card.Body>
                <Statistic title="Members" value={summary.totalMembers} />
              </Card.Body>
            </Card>
          </Col>

          <Col xl={3} md={6}>
            <Card className="h-100 border-0 shadow-sm">
              <Card.Body>
                <Statistic title="Machines" value={summary.totalDevices} />
              </Card.Body>
            </Card>
          </Col>
        </Row> */}

        <Card className="border-0 shadow-sm mb-4">
          <Card.Body>
            <Row className="g-3 align-items-end">
              <Col lg={3} md={6}>
                <FloatingLabel label="Search member or machine">
                  <Form.Control
                    type="text"
                    value={searchText}
                    placeholder="Search member or machine"
                    onChange={(event) => setSearchText(event.target.value)}
                    onKeyDown={(event) => {
                      if (event.key === "Enter") {
                        applyFilters();
                      }
                    }}
                  />
                </FloatingLabel>
              </Col>

              <Col lg={3} md={6}>
                <FloatingLabel label="Branch">
                  <Form.Select
                    value={branchFilter}
                    onChange={(event) => setBranchFilter(event.target.value)}
                    disabled={!canViewAllBranches}
                  >
                    {canViewAllBranches && (
                      <option value="">All Branches</option>
                    )}

                    {!canViewAllBranches && (
                      <option value={userBranchId}>
                        {userData?.branch_name || `Branch ${userBranchId}`}
                      </option>
                    )}

                    {canViewAllBranches &&
                      branches.map((branch) => {
                        const branchId =
                          branch?.fld_branch_id ||
                          branch?.branch_id ||
                          branch?.branchId ||
                          branch?.id ||
                          "";

                        const branchName =
                          branch?.fld_branch_name ||
                          branch?.branch_name ||
                          branch?.name ||
                          branch?.location ||
                          `Branch ${branchId}`;

                        return (
                          <option key={branchId} value={branchId}>
                            {branchName}
                          </option>
                        );
                      })}
                  </Form.Select>
                </FloatingLabel>
              </Col>

              <Col lg={3} md={6}>
                <RangePicker
                  value={dates}
                  format="DD-MM-YYYY"
                  className="w-100 py-3"
                  allowClear
                  onChange={(value) => setDates(value)}
                  disabledDate={(current) =>
                    current && current.isAfter(dayjs().endOf("day"))
                  }
                />
              </Col>

              <Col lg={3} md={6}>
                <FloatingLabel label="Punch Type">
                  <Form.Select
                    value={punchType}
                    onChange={(event) => setPunchType(event.target.value)}
                  >
                    <option value="">All</option>
                    <option value="IN">IN</option>
                    <option value="OUT">OUT</option>
                  </Form.Select>
                </FloatingLabel>
              </Col>

              <Col lg={3} md={6}>
                <div className="d-flex gap-2">
                  <Button
                    variant="dark"
                    className="w-100 py-2"
                    disabled={loading}
                    onClick={applyFilters}
                  >
                    Apply
                  </Button>

                  <Button
                    variant="outline-secondary"
                    className="w-100 py-2"
                    disabled={loading}
                    onClick={clearFilters}
                  >
                    Clear
                  </Button>
                </div>
              </Col>
              <Col lg={9} md={6}>
                <div className="d-flex justify-content-end align-items-center">
                  <p className="mb-0">Total Attendence: </p>
                  <Statistic value={summary.totalIN} />
                </div>
              </Col>
            </Row>
          </Card.Body>
        </Card>

        <Row>
          <Col lg={12}>
            <Table
              rowKey={(record) => record.id}
              size="small"
              bordered
              loading={loading}
              className="customTable"
              columns={columns}
              dataSource={attendanceData}
              scroll={{
                x: 1450,
              }}
              locale={{
                emptyText: <Empty description="No attendance records found" />,
              }}
              pagination={{
                current: page,
                pageSize,
                total,
                showSizeChanger: false,
                showQuickJumper: true,
                position: ["bottomRight"],
                showTotal: (recordTotal, range) =>
                  `${range[0]}-${range[1]} of ${recordTotal} records`,
                onChange: (newPage) => {
                  setPage(newPage);
                },
              }}
            />
          </Col>
        </Row>
      </Container>
    </section>
  );
}

export default Attendence;
